self.addEventListener("push",t=>{if(!t.data)return;let i={title:"\uD83D\uDD25 Special Offer from Hive!",body:"Tap to explore new collections."};try{i=t.data.json()}catch(e){i.body=t.data.text()}let e={body:i.body||"Check out new arrivals on Hive.",icon:i.icon||"/icon.png",badge:i.badge||"/icon.png",image:i.bannerUrl,tag:"hive-customer-campaign",renotify:!0,vibrate:[200,100,200],data:{url:i.targetUrl||"/"},actions:[{action:"explore",title:"\uD83D\uDECD️ Shop Now"},{action:"dismiss",title:"Close"}]};t.waitUntil(self.registration.showNotification(i.title||"Hive Notification",e))}),self.addEventListener("notificationclick",t=>{if(t.notification.close(),"dismiss"===t.action)return;let i=t.notification.data&&t.notification.data.url||"/";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let e of t)if(e.url&&"focus"in e)return"navigate"in e&&e.navigate(i),e.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))});